// The lane's work, as isolated fan-out tasks. Each gets its own worktree +
// branch + self-verify; failed verifies are reported, not merged.
// Tune verify commands to the repo (npm/pnpm/pip/cargo...).
return [{ json: {
  repo: 'repo',
  base: 'main',
  clean: true,   // re-runnable weekly: replaces last week's unmerged branches
  tasks: [
    { id: 'security-bumps',
      prompt: 'Run a dependency audit and upgrade ONLY packages with known security advisories. Keep changes minimal (patch/minor where possible), update the lockfile, and note each CVE addressed in the commit-worthy summary.',
      verify: 'npm audit --audit-level=high && npm test' },
    { id: 'minor-bumps',
      prompt: 'Upgrade dependencies to their latest MINOR/PATCH versions only — no major-version jumps. Update the lockfile. If an upgrade breaks tests, revert that single package and note it.',
      verify: 'npm test' },
    { id: 'stale-report',
      prompt: 'Produce a report of remaining outdated MAJOR-version dependencies: package, current vs latest, changelog highlights, migration risk (low/med/high). Write it to UPGRADES.md. Do not upgrade anything.',
      verify: 'test -f UPGRADES.md' }
  ]
} }];

const r = $input.first().json;
const results = r.results || [];
const ready = results.filter(x => x.patchFile && x.verify?.passed);
const failed = results.filter(x => x.status === 'failed' || x.status === 'error');
const lines = results.map(x =>
  `- ${x.id} [${x.status}]` +
  (x.verify ? ` verify:${x.verify.passed ? 'PASS' : 'FAIL'}` : '') +
  (x.diffStat ? ` (${x.diffStat.split('\n').pop().trim()})` : ''));
return [{ json: {
  severity: failed.length ? 'warn' : 'info',
  title: `Dependency lane: ${ready.length} branch(es) merge-ready, ${failed.length} need attention`,
  message: `${r.review || ''}\n\n${lines.join('\n')}\n\nMerge the green ones: git merge agent/<id> — merge stays a human act.`,
  source: 'dependency-bumps'
} }];
